import axios from "axios";

const BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";

const api = axios.create({ baseURL: BASE });

api.interceptors.request.use((config) => {
  const token = localStorage.getItem("crisp_token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// ── Auth ──────────────────────────────────────────────────────────────────────
export const login    = (username, password) =>
  api.post("/api/auth/login", { username, password });

export const register = (username, password, fullName) =>
  api.post("/api/auth/register", { username, password, fullName });

// ── Rooms ─────────────────────────────────────────────────────────────────────
export const getUserRooms   = (username) => api.get(`/api/rooms/user/${username}`);
export const createRoom     = (body)     => api.post("/api/rooms/create", body);
export const getChatHistory = (roomId)   => api.get(`/api/rooms/${roomId}/history`);

// ── Users ─────────────────────────────────────────────────────────────────────
export const getAllUsers    = ()         => api.get("/api/users");
export const getOnlineUsers = ()        => api.get("/api/users/online");

// Feature: Last Seen — fetch a single user's status + lastSeen
export const getUserStatus  = (username) => api.get(`/api/users/${username}`);

export default api;
